def read(p,key):return p.evaluate('k=>JSON.parse(localStorage.getItem(k))',key)
def fail(p,operation):p.evaluate('op=>sessionStorage.setItem("dujia-prototype-fail-next",op)',operation)
def landed(p,id):p.wait_for_url('**/'+id+'.html*')
def nav(p,label):p.locator('body>nav').get_by_role('button',name=label,exact=True).click()
def stage(p,steps,name):
 p.evaluate('document.fonts.ready');expect(p.locator('[aria-busy=true]')).to_have_count(0);snapshot={k:read(p,'dujia-prototype-'+k) for k in ['records','moments','works','books','pet','relationship','session']};steps.append(dict(step=name,url=p.url,snapshot=snapshot));print('STEP '+name,flush=True)
 if name in ['book-published','relogin-content-retained','book-deleted-sources-retained']:p.screenshot(path=str(SHOTS/(name+'.png')),full_page=True)

